INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21EBTTT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'After a $15\\%$ increase, the value of a stock is $\\$69$. What was the value of the stock, in dollars, before the increase?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let the original value be $v$. After a $15\\%$ increase, the value is $1.15v = 69$. Solving gives $v = \\frac{69}{1.15} = 60$. The original value was $\\$60$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21GGD7R', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A printing shop charges $\\$7$ per copy plus a flat binding fee of $\\$19$ per order. A customer can spend at most $\\$103$ on a single order. What is the maximum number of copies the customer can include in the order?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$12$"},{"key":"C","text":"$14$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $n$ be the number of copies. The total cost is $7n + 19$, and the inequality $7n + 19 \\leq 103$ must hold. Subtracting $19$ from both sides gives $7n \\leq 84$, and dividing by $7$ gives $n \\leq 12$. The maximum number of copies is $12$. The distractor $11$ arises from incorrectly interpreting "at most" as requiring strictly less than $12$. The distractor $14$ results from omitting the binding fee and computing $103 \\div 7 \\approx 14.7$, rounding down to $14$. The distractor $15$ results from omitting the binding fee and rounding $103 \\div 7$ up to $15$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM232G4F7', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{7x^2 + 23x - 28}{x + 4}$ can be written in the form $ax + b + \\frac{c}{x + 4}$, where $a$, $b$, and $c$ are constants, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$-14$"},{"key":"C","text":"$6$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'A', NULL, E'Performing polynomial long division of $7x^2 + 23x - 28$ by $x + 4$: dividing $7x^2$ by $x$ gives $7x$; multiplying $7x(x + 4) = 7x^2 + 28x$; subtracting yields $(23x - 28x) = -5x - 28$; dividing $-5x$ by $x$ gives $-5$; multiplying $-5(x + 4) = -5x - 20$; subtracting yields $-28 - (-20) = -8$. So the expression equals $7x - 5 + \\frac{-8}{x + 4}$, meaning $a = 7$, $b = -5$, $c = -8$, and $a + b + c = 7 + (-5) + (-8) = -6$. The distractor $-14$ results from a sign error when computing the remainder, getting $-16$ instead of $-8$. The distractor $6$ comes from treating the remainder as $+8$ rather than $-8$. The distractor $14$ results from adding $|a| + |b| + |c|$ instead of the signed values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM238LR5D', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A carpenter charges a flat fee of $\\$67$ for a house call plus $\\$41$ per hour of labor. A plumber charges a flat fee of $\\$115$ plus $\\$29$ per hour of labor. After how many hours of work will the carpenter and the plumber charge the same total amount?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'The carpenter''s total charge is $41h + 67$ and the plumber''s total charge is $29h + 115$, where $h$ is the number of hours. Setting these equal: $41h + 67 = 29h + 115$. Subtracting $29h$ from both sides gives $12h + 67 = 115$. Subtracting $67$ from both sides gives $12h = 48$. Dividing by $12$ gives $h = 4$. Verification: the carpenter charges $41(4) + 67 = 231$ dollars and the plumber charges $29(4) + 115 = 231$ dollars, confirming both totals are equal at $4$ hours.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23CAGEY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A student''s scores on $5$ tests are $78, 83, 91, 69$, and one unknown score. If the mean of all $5$ scores is $82$, what is the unknown score?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '89', ARRAY['89'], E'The mean of $5$ scores is $82$, so the sum of all scores is $82 \\times 5 = 410$. The sum of the four known scores is $78 + 83 + 91 + 69 = 321$. The unknown score is $410 - 321 = 89$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23LQE9M', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x - 2y = 9$. Line $q$ is perpendicular to line $p$ and passes through the point $(4, -3)$. Which of the following is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5y = -7$"},{"key":"B","text":"$2x + 5y = 23$"},{"key":"C","text":"$5x - 2y = 26$"},{"key":"D","text":"$2x - 5y = 23$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $p$ in slope-intercept form: $y = \\frac{5}{2}x - \\frac{9}{2}$, so its slope is $\\frac{5}{2}$. A perpendicular line has slope $-\\frac{2}{5}$. Using point-slope form with $(4, -3)$: $y + 3 = -\\frac{2}{5}(x - 4)$, giving $y = -\\frac{2}{5}x + \\frac{8}{5} - 3 = -\\frac{2}{5}x - \\frac{7}{5}$. Multiplying by $5$: $5y = -2x - 7$, so $2x + 5y = -7$. The equation $2x + 5y = 23$ results from a sign error when substituting the point, using $y - 3$ instead of $y + 3$. The equation $5x - 2y = 26$ uses the original slope $\\frac{5}{2}$ rather than the perpendicular slope, showing a conceptual gap about perpendicular slopes. The equation $2x - 5y = 23$ uses slope $\\frac{2}{5}$ (positive) instead of $-\\frac{2}{5}$, omitting the negative in the negative reciprocal.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24HDN3U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new tutoring program improves test scores. She randomly assigns $60$ students to receive the tutoring and $60$ students to a control group that does not receive it. After $8$ weeks, she compares average test scores. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"An observational study"},{"key":"B","text":"A randomized experiment"},{"key":"C","text":"A survey"},{"key":"D","text":"A case study"}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researcher randomly assigned participants to a treatment group (tutoring) and a control group (no tutoring), this is a randomized experiment. An observational study would observe existing groups without assigning treatments. A survey collects self-reported data but does not impose a treatment. A case study is an in-depth analysis of a single individual or small group and does not involve random assignment to conditions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24HPPS9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer produces $37$ pages in $4$ minutes. At this constant rate, how many pages does the printer produce in $20$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$148$"},{"key":"B","text":"$185$"},{"key":"C","text":"$157$"},{"key":"D","text":"$740$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{37 \\text{ pages}}{4 \\text{ minutes}}$. In $20$ minutes the printer produces $\\frac{37}{4} \\times 20 = 37 \\times 5 = 185$ pages. The distractor $148$ comes from incorrectly computing $37 \\times 4$ instead of using the rate. The distractor $157$ results from a faulty setup such as $37 + 20 \\times 4 + 37$ or a similar miscombination of the given values. The distractor $740$ comes from multiplying $37 \\times 20$ without dividing by the $4$-minute interval, treating pages and minutes as directly multiplied.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26MTNF3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'The equation $$\\frac{a(3x - 8)}{5} = 4x - \\frac{12}{5}$$ has no solution. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{2}$"},{"key":"B","text":"$\\frac{20}{3}$"},{"key":"C","text":"$-\\frac{20}{3}$"},{"key":"D","text":"$\\frac{3}{20}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiplying both sides by $5$ gives $a(3x - 8) = 20x - 12$, which expands to $3ax - 8a = 20x - 12$. For the equation to have no solution, the coefficients of $x$ must be equal while the constant terms differ: $3a = 20$, so $a = \\frac{20}{3}$. Checking the constants: $-8 \\cdot \\frac{20}{3} = -\\frac{160}{3} \\neq -12$, confirming no solution exists. The value $\\frac{3}{2}$ comes from matching only the constant terms ($-8a = -12$, so $a = \\frac{3}{2}$) while ignoring the coefficient condition — this actually produces a unique solution, not no solution. The value $-\\frac{20}{3}$ introduces a sign error in the coefficient equation. The value $\\frac{3}{20}$ results from inverting $\\frac{20}{3}$, reflecting a conceptual error in solving $3a = 20$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM276G6RV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher finds that people who drink more than $3$ cups of herbal tea per day have lower blood pressure on average than those who drink none. The researcher concludes that drinking herbal tea causes lower blood pressure. Which of the following is the most valid criticism of this conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The sample size may have been too small."},{"key":"B","text":"Because this is an observational study, confounding variables could explain the association."},{"key":"C","text":"The researcher should have measured heart rate instead of blood pressure."},{"key":"D","text":"The conclusion is valid because a correlation was observed."}]$lyceon_json$::jsonb, 'B', NULL, E'The study is observational because the researcher did not randomly assign people to drink or not drink herbal tea. In observational studies, confounding variables (such as overall diet, exercise habits, or stress levels) may explain the observed association, so a causal conclusion is not justified. While sample size could affect the reliability of results, the fundamental issue is the lack of random assignment, which prevents establishing causation. Measuring heart rate instead of blood pressure would change the research question entirely and is irrelevant. Claiming the conclusion is valid because a correlation exists confuses correlation with causation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27X8OJ0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A wildlife survey finds $84$ herons and $132$ egrets at Lake A. Lake B has herons and egrets in the same ratio as Lake A but contains $198$ egrets. How many herons are at Lake B?', NULL, $lyceon_json$[{"key":"A","text":"$116$"},{"key":"B","text":"$126$"},{"key":"C","text":"$132$"},{"key":"D","text":"$150$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of herons to egrets at Lake A is $\\frac{84}{132}$. Dividing both by $12$ gives $\\frac{7}{11}$. At Lake B, $198$ egrets correspond to $\\frac{198}{11} = 18$ units, so herons $= 7 \\times 18 = 126$. The distractor $116$ results from a multiplication error such as computing $7 \\times 18$ as $116$. The distractor $132$ comes from assuming Lake B has the same count of herons as Lake A has egrets, confusing the two quantities. The distractor $150$ arises from an additive approach such as $198 - 132 + 84 = 150$ instead of using a multiplicative ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM284BOSI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 2x^2 - 9$. What is the value of $g(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-27$"},{"key":"C","text":"$27$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = -3$: $g(-3) = 2(-3)^2 - 9 = 2(9) - 9 = 18 - 9 = 9$. The distractor $-27$ comes from incorrectly computing $(-3)^2$ as $-9$ instead of $9$, giving $2(-9) - 9 = -27$. The distractor $27$ results from computing $2(9) + 9 = 27$ by adding instead of subtracting. The distractor $-9$ comes from ignoring the $2x^2$ term and only seeing the constant $-9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AX2M1H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $7$ red marbles, $4$ blue marbles, and $3$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{7}$"},{"key":"B","text":"$\\frac{1}{3}$"},{"key":"C","text":"$\\frac{4}{11}$"},{"key":"D","text":"$\\frac{3}{14}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $7 + 4 + 3 = 14$. The probability of selecting a blue marble is $\\frac{4}{14} = \\frac{2}{7}$. The fraction $\\frac{1}{3}$ incorrectly assumes that each of the three colors is equally likely, ignoring that the colors have different counts. The fraction $\\frac{4}{11}$ results from using only $7 + 4 = 11$ as the denominator, omitting the green marbles. The fraction $\\frac{3}{14}$ is the probability of selecting a green marble, not blue.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BTN71R', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $9x + ky = 54$ and $3x + 11y = 18$ has infinitely many solutions. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$11$"},{"key":"C","text":"$27$"},{"key":"D","text":"$33$"}]$lyceon_json$::jsonb, 'D', NULL, E'For the system to have infinitely many solutions, the two equations must be equivalent — meaning one is a constant multiple of the other. Dividing the first equation''s coefficients by the second''s: $\\frac{9}{3} = 3$ and $\\frac{54}{18} = 3$, so every coefficient in the first equation is $3$ times the corresponding coefficient in the second. Therefore $k = 3 \\times 11 = 33$. The distractor $3$ is the ratio itself, reflecting only partial reasoning (finding the multiplier but not applying it to $11$). The distractor $11$ results from assuming $k$ must equal the $y$-coefficient in the other equation. The distractor $27$ comes from multiplying $9 \\times 3 = 27$ instead of $11 \\times 3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BW1VRT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution to the equation $x^2 - 3x - 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factoring the quadratic: $x^2 - 3x - 28 = (x - 7)(x + 4) = 0$. Setting each factor to zero gives $x = 7$ or $x = -4$. The positive solution is $7$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2COQ2P3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'grid_in', E'A data set contains the values $14, 19, 23, 27, 31, 38$. What is the median of this data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'The data set has $6$ values listed in increasing order. The median of an even-count data set is the average of the two middle values. The $3$rd and $4$th values are $23$ and $27$, so the median is $\\frac{23 + 27}{2} = \\frac{50}{2} = 25$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CRKKQV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveyed a random sample of $600$ residents in a county and found that $37\\%$ of them use public transit regularly. The margin of error is $\\pm 3$ percentage points at a $95\\%$ confidence level. A second researcher surveys a random sample of $150$ residents of the same county. Which of the following is most likely true about the second survey''s margin of error at the same confidence level?', NULL, $lyceon_json$[{"key":"A","text":"It will be less than $3$ percentage points."},{"key":"B","text":"It will be exactly $3$ percentage points."},{"key":"C","text":"It will be greater than $3$ percentage points."},{"key":"D","text":"It cannot be determined without knowing the second survey's results."}]$lyceon_json$::jsonb, 'C', NULL, E'Margin of error decreases as sample size increases (it is inversely proportional to the square root of the sample size). Since the second survey uses $150$ residents, which is smaller than the first survey''s $600$ residents, the margin of error will be larger than $3$ percentage points at the same confidence level. A smaller margin of error would require a larger sample, not a smaller one. The margin of error depends on sample size and confidence level, so it will not remain exactly the same with a different sample size. While the exact margin depends on the observed proportion, the direction of change (larger) is determined by the smaller sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D7GBBG', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'The point $(3, k)$ lies on the line $9x - 4y = 47$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-5', ARRAY['-5'], E'Substituting $x = 3$ into the equation gives $9(3) - 4k = 47$, which simplifies to $27 - 4k = 47$. Subtracting $27$ from both sides yields $-4k = 20$, and dividing by $-4$ gives $k = -5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DKFFXZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tests a new sleep aid by randomly assigning $500$ volunteers to receive either the sleep aid or a placebo. Neither the participants nor the researchers administering the treatment know which group each participant is in. After $6$ weeks, the group receiving the sleep aid reports falling asleep an average of $13$ minutes faster, and the result is statistically significant. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The sleep aid causes people in the general population to fall asleep faster."},{"key":"B","text":"The sleep aid likely causes volunteers similar to those in the study to fall asleep faster."},{"key":"C","text":"The placebo effect alone explains the $13$-minute difference."},{"key":"D","text":"A larger study would show no significant difference."}]$lyceon_json$::jsonb, 'B', NULL, E'The study is a double-blind randomized controlled experiment, which supports causal conclusions. However, the participants are volunteers, not a random sample of the general population, so the results can be generalized only to people similar to the volunteers, not to the entire population. Claiming the result applies to the general population overgeneralizes beyond the study''s sample. The use of a placebo control and blinding specifically accounts for the placebo effect, so attributing the difference to placebo alone contradicts the study design. Asserting that a larger study would show no difference contradicts the statistically significant finding and has no basis in the information given.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E573GI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $7$ cm and a height of $18$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$882\\pi \\text{ cm}^3$"},{"key":"B","text":"$252\\pi \\text{ cm}^3$"},{"key":"C","text":"$126\\pi \\text{ cm}^3$"},{"key":"D","text":"$1764\\pi \\text{ cm}^3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(7)^2(18) = \\pi(49)(18) = 882\\pi$ cubic centimeters. The $252\\pi$ result uses the lateral surface area formula $2\\pi r h = 2(7)(18)\\pi = 252\\pi$ instead of volume. The $126\\pi$ result uses $\\pi r h = \\pi(7)(18) = 126\\pi$, forgetting to square the radius. The $1764\\pi$ result squares both the radius and the height: $\\pi(49)(36) = 1764\\pi$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EBI2MT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The data set $\\{3, 7, 11, 15, k, 23, 29\\}$ is listed in increasing order, and $15 < k < 23$. If the mean of the data set equals its median, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Since the data set has $7$ values in increasing order and $15 < k < 23$, the sorted order is $3, 7, 11, 15, k, 23, 29$, and the median is the $4$th value, which is $15$. The mean is $\\frac{3 + 7 + 11 + 15 + k + 23 + 29}{7} = \\frac{88 + k}{7}$. Setting the mean equal to the median: $\\frac{88 + k}{7} = 15$, so $88 + k = 105$ and $k = 17$. Since $15 < 17 < 23$, this is consistent with the given ordering.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EP3ZH6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(2x - 7) + 4x$?', NULL, $lyceon_json$[{"key":"A","text":"$10x - 21$"},{"key":"B","text":"$10x - 7$"},{"key":"C","text":"$6x - 21$"},{"key":"D","text":"$10x + 21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing $3$ across $(2x - 7)$ gives $6x - 21$. Adding $4x$ yields $6x + 4x - 21 = 10x - 21$. The distractor $10x - 7$ results from failing to distribute the $3$ to the $-7$ term. The distractor $6x - 21$ comes from forgetting to add $4x$. The distractor $10x + 21$ results from incorrectly treating $3(-7)$ as $+21$ instead of $-21$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F6T8G7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, angle $A$ measures $46°$ and angle $B$ measures $79°$. Point $D$ lies on $\\overline{BC}$ such that $\\overline{AD}$ bisects angle $A$. What is the measure, in degrees, of angle $ADB$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '78', ARRAY['78'], E'First, angle $C = 180° - 46° - 79° = 55°$. Since $\\overline{AD}$ bisects angle $A$, angle $BAD = \\frac{46°}{2} = 23°$. In triangle $ABD$, the three angles are angle $ABD = 79°$, angle $BAD = 23°$, and angle $ADB$. By the triangle angle sum: $79° + 23° + \\text{angle } ADB = 180°$, so angle $ADB = 180° - 79° - 23° = 78°$. A common error is using the full angle $A$ of $46°$ in triangle $ABD$ instead of the bisected half, yielding $180° - 79° - 46° = 55°$. Another error is working in triangle $ADC$ and reporting angle $ADC = 180° - 78° = 102°$ when the question asks for angle $ADB$. A third error is forgetting to bisect angle $A$ and instead bisecting angle $B$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HHUDLH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of $31$ students, each student studies either French, Spanish, or both. There are $19$ students who study French and $23$ students who study Spanish. A student is selected at random from those who study French. What is the probability that this student also studies Spanish?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{31}$"},{"key":"B","text":"$\\frac{11}{23}$"},{"key":"C","text":"$\\frac{11}{19}$"},{"key":"D","text":"$\\frac{23}{31}$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the inclusion-exclusion principle, the number of students studying both languages is $19 + 23 - 31 = 11$. The conditional probability that a randomly selected French student also studies Spanish is $\\frac{11}{19}$, since there are $19$ French students and $11$ of them also study Spanish. The fraction $\\frac{11}{31}$ incorrectly uses the total class size as the denominator rather than conditioning on French students. The fraction $\\frac{11}{23}$ incorrectly conditions on Spanish students instead of French students. The fraction $\\frac{23}{31}$ gives the unconditional probability of studying Spanish, ignoring the condition that the student studies French.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I1TO4B', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = -4x + 53$. For what value of $x$ does $f(x) = 17$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$\\frac{35}{2}$"},{"key":"C","text":"$9$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting $f(x) = 17$ gives $-4x + 53 = 17$. Subtracting $53$ from both sides: $-4x = -36$. Dividing by $-4$: $x = 9$. The value $-9$ results from dividing $-36$ by $4$ instead of $-4$, a sign error. The value $\\frac{35}{2}$ comes from incorrectly adding $17 + 53 = 70$ and then dividing by $4$, rather than subtracting to get $-36$. The value $17$ confuses the function output with the input, reporting the given $f(x)$ value instead of solving for $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I7VHH2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher fits two models to a data set. Model A is $y = 2.1x + 5$ and Model B is $y = 0.3x^2 + 1.2x + 2$. At $x = 4$, the observed value of $y$ is $12.6$. What is the residual for Model B at $x = 4$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$-0.8$"},{"key":"C","text":"$1$"},{"key":"D","text":"$11.6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Model B predicts $y = 0.3(4)^2 + 1.2(4) + 2 = 0.3(16) + 4.8 + 2 = 4.8 + 4.8 + 2 = 11.6$. The residual is observed minus predicted: $12.6 - 11.6 = 1$. The distractor $-1$ reverses the residual formula to predicted minus observed ($11.6 - 12.6$), a sign error. The distractor $-0.8$ is the residual for Model A ($12.6 - 13.4 = -0.8$, since Model A gives $2.1(4) + 5 = 13.4$), answering for the wrong model. The distractor $11.6$ gives the predicted value itself rather than the difference between observed and predicted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JIMW2C', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations below has exactly one solution $(x, y)$.$$y = 4x - 23$$$$y = x^2 - 6x + 2$$What is the value of $y$ in the solution?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-23$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the expressions equal: $4x - 23 = x^2 - 6x + 2$. Rearranging: $x^2 - 10x + 25 = 0$, which factors as $(x - 5)^2 = 0$, so $x = 5$. Substituting into the linear equation: $y = 4(5) - 23 = 20 - 23 = -3$. The distractor $5$ gives the $x$-value instead of the $y$-value. The distractor $-23$ is just the constant from the linear equation, ignoring the $4x$ term. The distractor $17$ comes from substituting $x = 5$ into only $x^2 - 6x + 2$ incorrectly as $25 - 6 + 2 = 21$, then confusing intermediate values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JVIBQG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The equation $y = -0.4x + 89$ models the relationship between the number of absences $x$ and a student''s final grade $y$. What is the predicted final grade for a student with $13$ absences?', NULL, $lyceon_json$[{"key":"A","text":"$78.6$"},{"key":"B","text":"$83.8$"},{"key":"C","text":"$84.2$"},{"key":"D","text":"$94.2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 13$: $y = -0.4(13) + 89 = -5.2 + 89 = 83.8$. The distractor $94.2$ adds $5.2$ to $89$ instead of subtracting, making a sign error with the negative slope. The distractor $84.2$ results from computing $-0.4 \\times 12 + 89 = -4.8 + 89$, using $12$ absences instead of $13$. The distractor $78.6$ results from computing $-0.8 \\times 13 + 89 = -10.4 + 89$, doubling the magnitude of the slope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LBUR9E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $17$ meters and a width of $11$ meters. What is the area of the garden, in square meters?', NULL, $lyceon_json$[{"key":"A","text":"$187$"},{"key":"B","text":"$56$"},{"key":"C","text":"$28$"},{"key":"D","text":"$154$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a rectangle is length times width: $17 \\times 11 = 187$ square meters. The $56$ result computes the perimeter ($2(17 + 11) = 56$) instead of the area. The $28$ result computes half the perimeter ($17 + 11 = 28$). The $154$ result comes from an arithmetic error such as computing $14 \\times 11 = 154$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LLZE8C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $400$ voters in a city found that $58\\%$ support a proposed park renovation. The margin of error for the survey is $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $54\\%$ and $62\\%$ of voters in the sample support the renovation."},{"key":"B","text":"Exactly $58\\%$ of all voters in the city support the renovation."},{"key":"C","text":"It is plausible that between $54\\%$ and $62\\%$ of all voters in the city support the renovation."},{"key":"D","text":"If the survey were repeated, exactly $58\\%$ would again be the result."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error creates a confidence interval around the sample statistic to estimate the population parameter. Adding and subtracting $4$ percentage points from $58\\%$ gives a plausible range of $54\\%$ to $62\\%$ for all voters in the city. The interpretation that $54\\%$ to $62\\%$ describes the sample is incorrect because the sample result is already known to be $58\\%$; the margin of error applies to inference about the population. Stating that exactly $58\\%$ of all voters support the renovation ignores sampling variability. Claiming the survey would yield the same result if repeated confuses sample statistics with fixed values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MI97S7', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What are all values of $x$ that satisfy the inequality $13x - 5 > 60$?', NULL, $lyceon_json$[{"key":"A","text":"$x > 65$"},{"key":"B","text":"$x > 13$"},{"key":"C","text":"$x > 5$"},{"key":"D","text":"$x < 5$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $5$ to both sides gives $13x > 65$, and dividing both sides by $13$ gives $x > 5$. The distractor $x > 65$ results from adding $5$ to both sides but failing to divide by $13$. The distractor $x > 13$ comes from dividing $65$ by $5$ instead of by $13$. The distractor $x < 5$ incorrectly reverses the inequality direction when dividing by a positive number.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NKZZ0Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'The population of a town was $4{,}700$ in 2020. The population increased by $30\\%$ from 2020 to 2021 and then decreased by $20\\%$ from 2021 to 2022. What was the population in 2022?', NULL, $lyceon_json$[{"key":"A","text":"$4{,}700$"},{"key":"B","text":"$4{,}888$"},{"key":"C","text":"$5{,}170$"},{"key":"D","text":"$6{,}110$"}]$lyceon_json$::jsonb, 'B', NULL, E'In 2021, the population was $4{,}700 \\times 1.30 = 6{,}110$. In 2022, it was $6{,}110 \\times 0.80 = 4{,}888$. The distractor $4{,}700$ assumes the $30\\%$ increase and $20\\%$ decrease cancel each other and return to the original value, which is incorrect because the percentages are applied to different base values. The distractor $5{,}170$ results from treating the net change as $+10\\%$ of the original ($4{,}700 \\times 1.10 = 5{,}170$), incorrectly subtracting the percentages. The distractor $6{,}110$ computes only the first year''s increase and omits the second year''s decrease entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P1CBPV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $41°$ and the measure of angle $Q$ is $67°$. An exterior angle is formed at vertex $R$ by extending side $\\overline{QR}$. What is the measure of this exterior angle?', NULL, $lyceon_json$[{"key":"A","text":"$72°$"},{"key":"B","text":"$108°$"},{"key":"C","text":"$139°$"},{"key":"D","text":"$113°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The interior angle at $R$ is $180° - 41° - 67° = 72°$. The exterior angle at $R$ is supplementary to the interior angle: $180° - 72° = 108°$. Equivalently, the exterior angle equals the sum of the two non-adjacent interior angles: $41° + 67° = 108°$. The $72°$ result is the interior angle at $R$, not the exterior angle. The $139°$ result comes from incorrectly summing $67° + 72°$. The $113°$ result comes from an arithmetic error when subtracting from $180°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P2VQTA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A factory pump moves coolant at a rate of $17$ gallons per minute. There are $4$ quarts in $1$ gallon and $2$ pints in $1$ quart. How many pints of coolant does the pump move in $11$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$374$"},{"key":"B","text":"$748$"},{"key":"C","text":"$1{,}496$"},{"key":"D","text":"$2{,}992$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, find the total gallons: $17 \\times 11 = 187$ gallons. Convert gallons to quarts: $187 \\times 4 = 748$ quarts. Convert quarts to pints: $748 \\times 2 = 1{,}496$ pints. The distractor $374$ results from multiplying gallons by only $2$ instead of converting through quarts first ($187 \\times 2 = 374$), applying only one of the two conversion factors. The distractor $748$ stops at quarts without completing the conversion to pints. The distractor $2{,}992$ doubles the correct answer, applying an extra factor of $2$ as if there were an additional conversion step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"unit_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P7R1MC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone and a cylinder share the same circular base with radius $5$ cm and the same height of $21$ cm. What is the volume, in cubic centimeters, of the space inside the cylinder but outside the cone? Express your answer as a numerical coefficient of $\\pi$ (if the volume is $k\\pi$, enter $k$).', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '350', ARRAY['350'], E'The volume of the cylinder is $\\pi r^2 h = \\pi(5)^2(21) = 525\\pi$ cubic centimeters. The volume of the cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}(525\\pi) = 175\\pi$ cubic centimeters. The space inside the cylinder but outside the cone has volume $525\\pi - 175\\pi = 350\\pi$ cubic centimeters, so $k = 350$. A common error is forgetting the $\\frac{1}{3}$ factor for the cone, making both volumes equal and getting $0$. Another error is computing only $\\frac{2}{3}$ of the cone volume rather than subtracting the cone from the cylinder, yielding $\\frac{2}{3}(175) \\approx 116.7$. A third error is using the diameter instead of the radius, which would quadruple the result.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P99VFC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 3 \\cdot 2^x$. The function $g$ is defined by $g(x) = f(x + 2) - 5$. Which of the following is an equivalent form of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$12 \\cdot 2^x - 5$"},{"key":"B","text":"$3 \\cdot 2^x - 3$"},{"key":"C","text":"$6 \\cdot 2^x - 5$"},{"key":"D","text":"$3 \\cdot 4^x - 5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Evaluating $g(x) = f(x + 2) - 5 = 3 \\cdot 2^{x+2} - 5$. Applying the exponent rule $2^{x+2} = 2^x \\cdot 2^2 = 4 \\cdot 2^x$ gives $g(x) = 3 \\cdot 4 \\cdot 2^x - 5 = 12 \\cdot 2^x - 5$. The distractor $3 \\cdot 2^x - 3$ incorrectly adds $2$ to the coefficient and subtracts $2$ from the constant. The distractor $6 \\cdot 2^x - 5$ treats $2^{x+2}$ as $2 \\cdot 2^x$ instead of $4 \\cdot 2^x$, confusing addition in the exponent with multiplication by $2$. The distractor $3 \\cdot 4^x - 5$ incorrectly changes the base from $2$ to $4$ rather than applying the product-of-powers rule.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PJ6QD3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys $1{,}100$ randomly selected adults nationwide and finds that $41\\%$ favor a particular policy, with a margin of error of $\\pm 3$ percentage points at a $95\\%$ confidence level. A local newspaper reports: "A majority of adults oppose the policy." Based on the survey data, which of the following best evaluates the newspaper''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because $41\\%$ is less than $50\\%$."},{"key":"B","text":"The claim is not supported because the confidence interval includes values where supporters could be close to $50\\%$."},{"key":"C","text":"The claim is supported because even the upper end of the confidence interval, $44\\%$, is below $50\\%$."},{"key":"D","text":"The claim is not supported because the margin of error means the true value could be anywhere from $0\\%$ to $100\\%$."}]$lyceon_json$::jsonb, 'C', NULL, E'The $95\\%$ confidence interval for the proportion favoring the policy is $41\\% \\pm 3\\%$, which is $38\\%$ to $44\\%$. Since the entire confidence interval is below $50\\%$, it is plausible that fewer than half of adults favor the policy, meaning a majority oppose it. The newspaper''s claim is supported by the data. Simply noting that $41\\%$ is below $50\\%$ without considering the confidence interval is incomplete reasoning — it ignores the margin of error. Saying supporters "could be close to $50\\%$" is vague and ignores that even the upper bound of $44\\%$ is well below $50\\%$. The claim that the true value could be anywhere from $0\\%$ to $100\\%$ misrepresents how confidence intervals work.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PTYRIU', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A gym charges a one-time registration fee of $\\$43$ plus $\\$19$ per month of membership. Which function $f(m)$ gives the total cost, in dollars, for $m$ months of membership?', NULL, $lyceon_json$[{"key":"A","text":"$f(m) = 43m + 19$"},{"key":"B","text":"$f(m) = 19m + 43$"},{"key":"C","text":"$f(m) = 62m$"},{"key":"D","text":"$f(m) = 19m - 43$"}]$lyceon_json$::jsonb, 'B', NULL, E'The monthly rate of $\\$19$ is the per-unit cost that multiplies $m$, and the one-time fee of $\\$43$ is the constant, so $f(m) = 19m + 43$. The expression $43m + 19$ swaps the rate and the fixed fee, treating $\\$43$ as the monthly charge. The expression $62m$ adds $19$ and $43$ into a single rate, losing the distinction between a fixed fee and a recurring cost. The expression $19m - 43$ uses the correct rate but subtracts the registration fee instead of adding it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QJ6A31', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ students found that $84$ play a sport and $52$ are in the school band. Of those who play a sport, $17$ are also in the band. If a student is selected at random from those who play a sport, what is the probability that the student is also in the band?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{17}{200}$"},{"key":"B","text":"$\\frac{17}{84}$"},{"key":"C","text":"$\\frac{17}{52}$"},{"key":"D","text":"$\\frac{52}{84}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the student plays a sport, the relevant pool is the $84$ students who play a sport, and $17$ of them are also in the band. So the conditional probability is $\\frac{17}{84}$. Using $200$ as the denominator gives the probability of selecting a student who both plays a sport and is in the band from the entire group, not the conditional probability. Using $52$ as the denominator incorrectly conditions on being in the band rather than playing a sport. The ratio $\\frac{52}{84}$ incorrectly uses the total band membership as the numerator instead of the overlap.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RO8OIA', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^4 y^3 - 15x^2 y^5}{3x^2 y^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 y - 5y^3$"},{"key":"B","text":"$3x^2 y - 5x^2 y^3$"},{"key":"C","text":"$3x^2 y^2 - 5y^3$"},{"key":"D","text":"$6x^2 y - 12y^3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing each term by $3x^2 y^2$: $\\frac{9x^4 y^3}{3x^2 y^2} = 3x^{4-2} y^{3-2} = 3x^2 y$ and $\\frac{15x^2 y^5}{3x^2 y^2} = 5x^{2-2} y^{5-2} = 5y^3$. The result is $3x^2 y - 5y^3$. The distractor $3x^2 y - 5x^2 y^3$ fails to cancel $x^2$ from the second term. The distractor $3x^2 y^2 - 5y^3$ incorrectly computes the $y$ exponent in the first term as $3 - 2 = 2$ instead of $1$. The distractor $6x^2 y - 12y^3$ subtracts the denominator coefficient rather than dividing by it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SHF8VL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one of the acute angles measures $34°$. The side opposite this angle has length $11$. What is the length of the hypotenuse, to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$19.7$"},{"key":"B","text":"$16.3$"},{"key":"C","text":"$6.2$"},{"key":"D","text":"$13.3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using $\\sin(34°) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{11}{c}$, we get $c = \\frac{11}{\\sin(34°)} = \\frac{11}{0.5592} \\approx 19.7$. The $16.3$ result comes from using tangent incorrectly: $\\frac{11}{\\tan(34°)} = \\frac{11}{0.6745} \\approx 16.3$, which gives the adjacent side, not the hypotenuse. The $6.2$ result comes from multiplying $11 \\times \\sin(34°) \\approx 6.2$, inverting the relationship. The $13.3$ result comes from using cosine instead of sine: $\\frac{11}{\\cos(34°)} \\approx 13.3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SWQCJY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A jacket originally priced at $\\$73$ is on sale for $\\$21.90$ off the original price. What percent discount does this represent?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30', ARRAY['30'], E'The percent discount is $\\frac{21.90}{73} \\times 100 = 0.30 \\times 100 = 30\\%$. The computation $\\frac{21.90}{73}$ yields exactly $0.30$, so the discount is $30$ percent.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T2R7VT', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$\\begin{cases} x + 3y = 23 \\\\ x - y = 7 \\end{cases}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TJDEA5', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $4x - 7y = 28$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$4$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting gives $-7y = 28$, so $y = -4$. The value $4$ results from a sign error when dividing $28$ by $-7$. The value $7$ comes from finding the $x$-intercept instead (setting $y = 0$: $4x = 28$, $x = 7$) rather than the $y$-intercept. The value $-7$ confuses the coefficient of $y$ with the intercept value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UPC9YR', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'Which of the following ordered pairs $(x, y)$ satisfies both inequalities $2x - 7y < -3$ and $4x + 3y \\geq 29$?', NULL, $lyceon_json$[{"key":"A","text":"$(3, 1)$"},{"key":"B","text":"$(2, 5)$"},{"key":"C","text":"$(7, 2)$"},{"key":"D","text":"$(5, 3)$"}]$lyceon_json$::jsonb, 'D', NULL, E'Testing $(5, 3)$: the first inequality gives $2(5) - 7(3) = 10 - 21 = -11$, and $-11 < -3$ is true; the second inequality gives $4(5) + 3(3) = 20 + 9 = 29$, and $29 \\geq 29$ is true. Both are satisfied. For $(3, 1)$: $2(3) - 7(1) = -1$, and $-1 < -3$ is false. For $(2, 5)$: the first inequality gives $2(2) - 7(5) = -31 < -3$, which is true, but the second gives $4(2) + 3(5) = 23$, and $23 \\geq 29$ is false — this pair satisfies only the first inequality. For $(7, 2)$: $2(7) - 7(2) = 0$, and $0 < -3$ is false.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UYTDYG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $13x - 29 = 62$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$\\frac{33}{13}$"},{"key":"C","text":"$7$"},{"key":"D","text":"$91$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $29$ to both sides gives $13x = 91$, and dividing both sides by $13$ gives $x = 7$. The value $-7$ results from a sign error when dividing $91$ by $13$. The value $\\frac{33}{13}$ comes from subtracting $29$ from $62$ (getting $33$) and dividing by $13$, which reverses the operation order. The value $91$ results from stopping after finding $13x = 91$ without dividing by $13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VO5ABP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $4x^2 - 20x + 25 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discriminant is $b^2 - 4ac = (-20)^2 - 4(4)(25) = 400 - 400 = 0$. A discriminant of zero means the equation has exactly one distinct real solution (a repeated root), which is $x = \\frac{20}{8} = \\frac{5}{2}$. Choosing $0$ solutions incorrectly interprets a zero discriminant as meaning no real solutions. Choosing $2$ solutions reflects the misconception that every quadratic has two distinct real roots. Choosing $4$ confuses the leading coefficient with the number of solutions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W3FQ34', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies the equation $3(2x - 7) + 11 = 5x + 8$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$18$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing gives $6x - 21 + 11 = 5x + 8$, which simplifies to $6x - 10 = 5x + 8$. Subtracting $5x$ from both sides and adding $10$ yields $x = 18$. The value $4$ results from incorrectly distributing $3(2x - 7)$ as $6x - 7$ instead of $6x - 21$, leading to $6x - 7 + 11 = 5x + 8$ and $x = 4$. The value $-2$ comes from subtracting $10$ instead of adding it when isolating $x$, producing $x = 8 - 10 = -2$. The value $29$ results from ignoring the $+11$ term entirely, solving $6x - 21 = 5x + 8$ to get $x = 29$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WN7O8Y', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 14x + 4y + 32 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{21}$"},{"key":"B","text":"$21$"},{"key":"C","text":"$\\sqrt{32}$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square for $x$: $x^2 - 14x = (x - 7)^2 - 49$. Complete the square for $y$: $y^2 + 4y = (y + 2)^2 - 4$. Substituting: $(x - 7)^2 - 49 + (y + 2)^2 - 4 + 32 = 0$, so $(x - 7)^2 + (y + 2)^2 = 21$. The radius is $r = \\sqrt{21}$. The $21$ result takes $r^2 = 21$ as the radius without applying the square root. The $\\sqrt{32}$ result uses the constant term $32$ directly under the radical. The $7$ result takes half the coefficient of $x$ without completing the full calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XCX3TX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of lengths $9$ and $40$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$41$"},{"key":"B","text":"$49$"},{"key":"C","text":"$31$"},{"key":"D","text":"$\\sqrt{1519}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the Pythagorean theorem, $c = \\sqrt{9^2 + 40^2} = \\sqrt{81 + 1600} = \\sqrt{1681} = 41$. The $49$ result comes from adding the legs directly ($9 + 40 = 49$) instead of using the Pythagorean theorem. The $31$ result comes from subtracting the legs ($40 - 9 = 31$). The $\\sqrt{1519}$ result comes from subtracting rather than adding the squared values ($1600 - 81 = 1519$).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XLQJ6W', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$\\begin{cases} 7x - 3y = 23 \\\\ 4x - 3y = 11 \\end{cases}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y8CJ45', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = (x - 7)^2 + 3$. Which of the following correctly describes the vertex and direction of opening of the graph of $y = h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"Vertex at $(7, 3)$, opens upward"},{"key":"B","text":"Vertex at $(-7, 3)$, opens upward"},{"key":"C","text":"Vertex at $(7, -3)$, opens downward"},{"key":"D","text":"Vertex at $(-7, -3)$, opens downward"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $h(x) = (x - 7)^2 + 3$ is in vertex form $a(x - h)^2 + k$ with $a = 1$, vertex at $(7, 3)$. Since $a = 1 > 0$, the parabola opens upward. The distractor with vertex $(-7, 3)$ incorrectly negates the horizontal shift, reading $(x - 7)$ as shifting left by $7$. The distractor with vertex $(7, -3)$ incorrectly negates the vertical shift constant. The distractor with vertex $(-7, -3)$ reverses both signs and incorrectly concludes the parabola opens downward despite a positive leading coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YA9J9N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot relating hours studied ($x$) to test score ($y$) is $y = 4.3x + 51$. According to this model, by how many points does the predicted test score increase for each additional hour studied?', NULL, $lyceon_json$[{"key":"A","text":"$4.3$"},{"key":"B","text":"$8.6$"},{"key":"C","text":"$51$"},{"key":"D","text":"$55.3$"}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = 4.3x + 51$, the coefficient of $x$ is the slope, which represents the predicted increase in $y$ for each unit increase in $x$. Therefore the score increases by $4.3$ points per additional hour. The distractor $8.6$ incorrectly doubles the slope. The distractor $51$ confuses the $y$-intercept with the rate of change. The distractor $55.3$ adds the slope and intercept together ($4.3 + 51$), which has no meaningful interpretation in the model.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YM1OH1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $13$ units. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$26\\pi$"},{"key":"B","text":"$169\\pi$"},{"key":"C","text":"$13\\pi$"},{"key":"D","text":"$676\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a circle is $A = \\pi r^2 = \\pi(13)^2 = 169\\pi$. The $26\\pi$ result uses the circumference formula $2\\pi r = 2(13)\\pi$ instead of the area formula. The $13\\pi$ result uses $\\pi r$ instead of $\\pi r^2$, forgetting to square the radius. The $676\\pi$ result squares the diameter ($26^2 = 676$) instead of the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YTIGP1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A ramp rises at an angle of $7°$ from the horizontal ground. If the ramp covers a horizontal distance of $23$ feet, what is the vertical rise of the ramp, in feet, to the nearest tenth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2.8', ARRAY['14/5', '2.8'], E'The vertical rise is the side opposite the $7°$ angle, and the horizontal distance of $23$ feet is the side adjacent to the $7°$ angle. Using $\\tan(7°) = \\frac{\\text{rise}}{23}$, the rise equals $23 \\times \\tan(7°) = 23 \\times 0.12278 \\approx 2.8$ feet. A common error is using sine instead of tangent: $23 \\times \\sin(7°) \\approx 2.80$, which gives a very similar result for small angles but uses the wrong ratio. Another error is using cosine: $23 \\times \\cos(7°) \\approx 22.8$, confusing the adjacent and opposite sides. A third error is computing $\\frac{23}{\\tan(7°)} \\approx 187.3$, inverting the tangent ratio.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZIQRTC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $53°$. What is the measure of the alternate interior angle on the opposite side of the transversal?', NULL, $lyceon_json$[{"key":"A","text":"$53°$"},{"key":"B","text":"$127°$"},{"key":"C","text":"$37°$"},{"key":"D","text":"$143°$"}]$lyceon_json$::jsonb, 'A', NULL, E'Alternate interior angles formed by parallel lines and a transversal are congruent, so the angle measures $53°$. The $127°$ result comes from computing the supplement ($180° - 53°$) instead of recognizing congruence. The $37°$ result comes from subtracting from $90°$ as if the angles were complementary. The $143°$ result comes from subtracting $37°$ from $180°$, compounding the complementary error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZXEJ8L', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle centered at the origin has the equation $x^2 + y^2 = 169$. A chord of this circle has one endpoint at $(5, 12)$ and the other at $(a, 0)$ where $a < 0$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-13', ARRAY['-13'], E'Since the endpoint $(a, 0)$ lies on the circle $x^2 + y^2 = 169$, we have $a^2 + 0^2 = 169$, so $a^2 = 169$ and $a = \\pm 13$. Since $a < 0$, we get $a = -13$. First verify $(5, 12)$ is on the circle: $25 + 144 = 169$, confirmed. A common error is taking the positive root $a = 13$, ignoring the constraint $a < 0$. Another error is computing the distance between the two endpoints and setting it equal to the diameter. A third error is confusing the chord with a diameter and placing the second endpoint at $(-5, -12)$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2078NYE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A recent survey of public libraries across rural Appalachia revealed that many communities rely on these institutions for more than book lending. The availability of high-speed internet terminals, along with free digital literacy workshops, ______ local residents who might otherwise lack access to essential online services such as telehealth appointments and government benefit applications.', $lyceon_json$[{"key":"A","text":"serve"},{"key":"B","text":"have served"},{"key":"C","text":"serves"},{"key":"D","text":"are serving"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the verb is "availability," which is singular. The intervening prepositional phrase "of high-speed internet terminals" and the parenthetical phrase "along with free digital literacy workshops" do not change the number of the subject. A phrase introduced by "along with" is not equivalent to a compound subject joined by "and"; it is a parenthetical addition. Therefore, the verb must be singular: "serves." The options using plural verb forms — "serve," "have served," and "are serving" — all fail to agree with the singular subject "availability."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20G8AHT', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "precipitated" most nearly mean?', E'Historian Celeste Mbeki argues that the 1897 rinderpest epidemic in southern Africa precipitated a fundamental restructuring of pastoral economies. With cattle herds decimated almost overnight, communities that had relied on livestock as both currency and social capital were forced to adopt agricultural practices they had previously resisted, altering settlement patterns for generations.', $lyceon_json$[{"key":"A","text":"condensed"},{"key":"B","text":"triggered"},{"key":"C","text":"forecasted"},{"key":"D","text":"dissolved"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states the epidemic "precipitated a fundamental restructuring," meaning it triggered or caused that restructuring. "Condensed" refers to making something denser or more compact, which is incoherent when applied to restructuring an economy. "Forecasted" means predicted in advance, but the passage presents the restructuring as something that actually happened, not something merely predicted. "Dissolved" means to break apart into nothing, which contradicts the passage''s point that the epidemic produced a new economic structure rather than eliminating structure entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW211GN5A', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Ornithologist Pavel Krecek has proposed that the decline of European turtle-dove populations is driven primarily by habitat loss on their breeding grounds in western Europe, where intensive agriculture has eliminated the hedgerows and scrublands the birds depend on for nesting.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22B2BPB', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the purpose of the text?', E'When the playwright Lorraine Hansberry drafted early versions of what would become A Raisin in the Sun, she included a subplot about a Nigerian character''s disillusionment with pan-African idealism. This subplot was cut before the Broadway premiere, largely at the insistence of the production team, who feared it would alienate audiences unfamiliar with post-colonial politics. Literary scholar Kwame Adjei has argued that this editorial decision fundamentally altered the play''s intellectual scope, transforming it from a work that interrogated global Black solidarity into one more narrowly focused on American domestic aspiration. Adjei contends that recovering the excised material is essential to understanding Hansberry''s original political vision.', $lyceon_json$[{"key":"A","text":"To argue that the commercial success of a theatrical production depended on strategic editorial choices"},{"key":"B","text":"To present a scholar's claim that a well-known work was significantly reshaped by pre-production editing decisions"},{"key":"C","text":"To compare the dramatic techniques used in two different versions of the same play"},{"key":"D","text":"To challenge the prevailing critical consensus that a play's themes are primarily domestic in scope"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage introduces a cut subplot, explains why it was removed, and then presents Kwame Adjei''s argument that this removal fundamentally changed the play''s scope — making the text''s purpose to convey a scholar''s claim about pre-production editing reshaping a well-known work. The option about commercial success is wrong because the passage mentions the production team''s fear of alienating audiences, but the text''s purpose is not to argue that commercial success depended on those cuts. The option about comparing dramatic techniques is wrong because the passage does not analyze or compare the techniques used in different versions; it discusses thematic scope. The option about challenging a prevailing consensus is wrong because the passage does not identify any prevailing critical consensus — it presents Adjei''s individual claim about the excised material.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22E1RO5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Haber-Bosch process, developed in the early twentieth century, enabled the industrial synthesis of ammonia from atmospheric nitrogen and became indispensable for producing agricultural fertilizers. Without it, modern crop yields could not sustain global food demands. _______ the process consumes roughly two percent of the world''s total energy supply each year and generates approximately 1.4 percent of global carbon dioxide emissions, making it one of the largest single contributors to industrial greenhouse gas output.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"That is,"},{"key":"C","text":"However,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first two sentences establish the Haber-Bosch process as essential for food production. The sentence after the blank introduces its serious environmental costs — massive energy consumption and carbon emissions. This is a direct contrast between the process''s benefit and its drawback, requiring a concessive-contrast transition. The similarity transition is wrong because the environmental costs are not parallel to the benefits but opposed to them. The clarification transition is wrong because the environmental information does not restate or clarify the importance to agriculture — it introduces an entirely new dimension of evaluation. The rephrasing transition is wrong for the same reason: the environmental cost is new information, not a reformulation of the preceding claim about food production.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26L6VGD', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1: Soil scientist Yuki Tanabe has argued that regenerative agriculture practices — including cover cropping, reduced tillage, and integrated livestock grazing — can sequester enough atmospheric carbon in topsoil to meaningfully offset agricultural emissions. Tanabe emphasizes that these techniques also improve soil water retention and microbial biodiversity, producing compounding ecological benefits that make carbon sequestration a secondary advantage rather than the sole justification.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26RA3QO', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "sustained" most nearly mean?', E'Marine biologists studying coral bleaching events in the Andaman Sea found that colonies of Porites lobata sustained visible damage within forty-eight hours of a thermal spike. Unlike faster-growing species that sometimes recover pigmentation quickly, Porites lobata showed discoloration persisting for months, suggesting that the damage was not superficial.', $lyceon_json$[{"key":"A","text":"suffered"},{"key":"B","text":"nourished"},{"key":"C","text":"prolonged"},{"key":"D","text":"championed"}]$lyceon_json$::jsonb, 'A', NULL, E'In the passage, the coral colonies "sustained visible damage," meaning they suffered or experienced damage. "Nourished" means to feed or provide sustenance, which is denotationally wrong because the passage describes harm, not feeding. "Prolonged" means to extend in duration; while "sustained" can mean ongoing, the sentence structure here uses "sustained" as a verb meaning to undergo damage, not to lengthen it. "Championed" means to advocate for a cause, which has no coherent meaning in the context of damage to coral.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27BH0SZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Tomoko Harada''s excavation at a seventh-century site in Nara Prefecture uncovered ceramic fragments whose glaze composition matched materials sourced from kilns over 800 kilometers away in Kyushu. Prior scholarship had assumed that pottery trade networks of this period were confined to regional clusters no larger than 200 kilometers in diameter. _______ Harada proposes that a centralized distribution system, possibly administered by early Yamato court officials, facilitated the movement of finished goods across far greater distances than local barter networks could have achieved.', $lyceon_json$[{"key":"A","text":"To explain this discrepancy,"},{"key":"B","text":"By comparison,"},{"key":"C","text":"In summary,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes a tension between the new finding (materials from 800 km away) and the prior assumption (trade limited to 200 km). The final sentence presents Harada''s hypothesis to account for this gap. The transition explaining a discrepancy correctly signals that the upcoming sentence offers a resolution to the contradiction just described. The comparison transition is wrong because Harada''s proposal is not comparing two equivalent subjects — it is resolving a conflict between evidence and prior belief. The summary transition is wrong because the final sentence introduces a new hypothesis rather than restating prior content. The concession transition is wrong because Harada is not conceding a point to an opposing argument; she is offering an explanatory mechanism for surprising evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29935J6', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists studying harbor seals along the coast of Nova Scotia have hypothesized that the seals preferentially hunt during the two hours surrounding dawn because prey fish school most densely near the surface at that time. The researchers tracked 37 seals with GPS-enabled dive loggers over a 14-month period and recorded both the timing and depth of feeding dives.', $lyceon_json$[{"key":"A","text":"Seals fitted with dive loggers consumed an average of 4.2 kilograms of fish per day, roughly consistent with estimates from captive feeding studies."},{"key":"B","text":"The density of prey fish within 15 meters of the surface peaked sharply during the hour before and after sunrise."},{"key":"C","text":"Harbor seals in the study area had a lower resting metabolic rate than harbor seals in warmer Pacific waters."},{"key":"D","text":"Several tagged seals migrated to deeper offshore waters during the winter months and returned to coastal areas in spring."}]$lyceon_json$::jsonb, 'B', NULL, E'The hypothesis states that seals hunt at dawn because prey fish school densely near the surface at that time. A finding that prey fish density near the surface peaks around sunrise would directly confirm the proposed mechanism. A finding about daily fish consumption matches general feeding data but does not address the specific timing-and-density mechanism the hypothesis proposes. A comparison of metabolic rates between populations is unrelated to the timing of prey availability. Seasonal migration patterns concern geographic movement, not the within-day hunting schedule that the hypothesis seeks to explain.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BFLNVR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the city council of Brattleboro, Vermont, convened in March 2023 to discuss proposed zoning amendments, several residents argued that the changes ______ disproportionately affect small businesses on Main Street. The council, however, maintained that the amendments were necessary to accommodate projected population growth over the next two decades.', $lyceon_json$[{"key":"A","text":"will"},{"key":"B","text":"would"},{"key":"C","text":"could have"},{"key":"D","text":"should"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence uses indirect (reported) speech introduced by the past-tense verb "argued." In Standard English, reported speech following a past-tense reporting verb requires the backshifted form: "will" becomes "would." The option "would" correctly maintains this sequence-of-tenses rule. The option "will" fails to backshift, violating the tense sequence established by the past-tense "argued." The option "could have" incorrectly introduces a past conditional that implies a hypothetical scenario that has already passed, rather than a prediction about future effects. The option "should" changes the meaning from a prediction to a statement of obligation, misrepresenting what the residents argued.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D1SEDQ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to present aerogels to an audience unfamiliar with them by explaining what they are and providing an example of their practical use. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a report on materials science, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D9HHG4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Gothenburg recently discovered that certain species of deep-sea sponges can filter dissolved organic carbon from surrounding water at rates previously thought impossible for invertebrates. _______ their findings suggest that sponges may play a far more significant role in oceanic carbon cycling than marine biologists had recognized.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence presents a conclusion that follows directly from the discovery described in the first sentence: because sponges filter carbon at unexpectedly high rates, they may be more important to carbon cycling than previously thought. This is a cause-and-effect relationship, so the result-indicating transition is correct. The contrast-indicating transition is wrong because the second sentence does not oppose the first. The example-indicating transition is wrong because the second sentence is a conclusion, not an illustration. The concurrent-action transition is wrong because the second sentence is not describing a simultaneous but unrelated event.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EB5F7L', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Historian Elif Karagöz has argued that the Ottoman Empire''s 16th-century adoption of the çift-hane system — in which peasant households were granted standardized agricultural plots in exchange for fixed tax obligations — was not merely an administrative convenience but a deliberate strategy to limit the power of provincial landholders. Under the system, the state retained ultimate ownership of the land, preventing local elites from accumulating large estates that could serve as bases for political autonomy. However, Karagöz notes that by the late 17th century, provincial magnates had effectively circumvented the system by securing lifetime tax-farming contracts (malikâne) that gave them de facto control over vast tracts. Karagöz therefore concludes that the çift-hane system ________', $lyceon_json$[{"key":"A","text":"succeeded in centralizing land control for roughly a century but ultimately failed to prevent the very concentration of provincial power it was designed to forestall."},{"key":"B","text":"was the primary cause of the Ottoman Empire's economic decline in the 18th century because it discouraged agricultural innovation."},{"key":"C","text":"was widely admired by European monarchs, who attempted to implement similar land-tenure systems in their own territories."},{"key":"D","text":"remained effective as a tool of central control throughout the Ottoman period because the state could revoke malikâne contracts at will."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the çift-hane system as designed to limit provincial power, then notes that by the late 17th century, provincial magnates circumvented it through malikâne contracts. The logical conclusion is that the system worked for a time but ultimately failed to prevent the provincial power consolidation it was intended to block. The claim about causing economic decline through discouraging agricultural innovation introduces a causal relationship and topic the passage never addresses. The assertion about European monarchs adopting similar systems has no basis in the passage. The suggestion that the system remained effective because the state could revoke malikâne contracts contradicts the passage, which describes magnates as having effectively circumvented the system, implying the state could not simply undo their arrangements.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F77LXJ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to emphasize the environmental benefit of the restoration project. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a presentation on urban green spaces, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FMXIF7', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine the traditional explanation described in the text?', E'Geologists have traditionally attributed the unusually high elevation of the Colorado Plateau — which sits roughly 2,100 meters above sea level despite lacking the crustal thickening typical of mountain-building zones — to thermal buoyancy from a region of anomalously hot mantle rock beneath the plateau. A 2021 seismic tomography study led by geophysicist Priya Venkataraman used data from 1,400 broadband seismometers to construct a three-dimensional velocity model of the upper mantle beneath the plateau. The study aimed to determine whether the thermal anomaly posited by the buoyancy model is actually present.', $lyceon_json$[{"key":"A","text":"Seismic wave velocities beneath the Colorado Plateau were uniformly high, indicating that the upper mantle in the region is cooler and denser than the buoyancy model predicts."},{"key":"B","text":"The Colorado Plateau's surface rocks include marine limestone deposits dating to roughly 300 million years ago, confirming that the region was once at or below sea level."},{"key":"C","text":"Broadband seismometers used in the study detected minor seismic activity along the plateau's western boundary consistent with ongoing tectonic adjustment."},{"key":"D","text":"Crustal thickness beneath the Colorado Plateau was found to average 43 kilometers, slightly greater than the 40-kilometer continental average."}]$lyceon_json$::jsonb, 'A', NULL, E'The traditional explanation attributes the plateau''s elevation to hot, buoyant mantle beneath it. A finding of uniformly high seismic velocities — which indicate cool, dense mantle rather than the hot, low-density material the model requires — would directly contradict the thermal buoyancy hypothesis. The presence of ancient marine limestone confirms past low elevation but says nothing about the current mantle thermal state, so it neither supports nor undermines the buoyancy model. Minor seismic activity along a boundary suggests tectonic processes but does not address whether the mantle beneath the plateau is anomalously hot. Slightly above-average crustal thickness is tangentially related to elevation but does not bear on the specific question of whether a thermal anomaly exists in the mantle.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FZHKS9', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Psychologist Ingrid Solheim has argued that bilingual children develop stronger executive function skills than their monolingual peers because the constant need to suppress one language while using the other exercises the brain''s inhibitory control mechanisms. Solheim cites studies showing that bilingual four-year-olds outperform monolinguals on tasks requiring them to ignore conflicting visual cues.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G0IAFT', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "temper" most nearly mean?', E'In a 2023 commentary on judicial philosophy, legal scholar Adaora Okonkwo contended that originalist interpretations of constitutional provisions must be tempered by evolving societal norms. She noted that jurists who refuse any adaptation risk rendering foundational legal texts irrelevant to the communities they are meant to govern, while those who abandon historical grounding altogether invite interpretive chaos.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"moderated"},{"key":"C","text":"provoked"},{"key":"D","text":"forged"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage argues that originalist interpretations must be "tempered by evolving societal norms," meaning they should be moderated or softened by those norms to avoid rigidity. "Heated" means to raise temperature or intensify emotion, which contradicts the passage''s argument for balance between strict originalism and adaptation. "Provoked" means to deliberately incite anger or a reaction, which is incoherent because evolving norms are not inciting the interpretations but rather balancing them. "Forged" means to create through intense effort or to shape metal, but the passage is not about creating interpretations from scratch — it is about adjusting existing ones.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HE9MGJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the 1970s, linguist William Labov recorded spontaneous speech from 63 residents of Martha''s Vineyard, Massachusetts, and found that younger islanders who intended to remain on the island were significantly more likely to use a centralized vowel pronunciation characteristic of older Vineyarder speech. By contrast, younger islanders planning to leave for the mainland showed vowel patterns closer to standard mainland American English. Labov concluded that the centralized pronunciation served as a marker of local identity, and that speakers were unconsciously intensifying it as a way of ________', $lyceon_json$[{"key":"A","text":"signaling their commitment to the island community and distinguishing themselves from outsiders."},{"key":"B","text":"preserving an archaic dialect that linguists feared would disappear within a single generation."},{"key":"C","text":"demonstrating their awareness of the phonological differences between island and mainland speech."},{"key":"D","text":"resisting the economic pressures that were driving many young people to leave the island."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that the centralized pronunciation served as a marker of local identity and was intensified by those planning to stay. The logical completion is that speakers used it to signal community commitment and differentiate from outsiders, which aligns with the identity-marking function Labov identified. The suggestion about preserving an archaic dialect goes beyond the passage, which frames the pronunciation as an active identity marker rather than a conservation effort, and never mentions linguists fearing its disappearance. The claim about demonstrating awareness of phonological differences misreads the passage''s emphasis: Labov describes the shift as unconscious, not as a deliberate display of linguistic knowledge. The idea of resisting economic pressures introduces a socioeconomic motive the passage does not discuss; the passage focuses on identity expression, not economic resistance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IK0ILI', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Economists have long modeled consumer behavior using the assumption of rational utility maximization, in which individuals weigh costs and benefits to make optimal purchasing decisions. However, behavioral economist Meera Rajagopalan''s 2019 study of 4,700 online shoppers found that 61% of participants abandoned purchases they had rated as high-value when the checkout process exceeded four steps, even though the final price remained unchanged. Rajagopalan argues that this pattern reflects cognitive depletion rather than revised preference: participants did not downgrade the product''s desirability but simply lacked the attentional resources to complete a multi-step transaction. Her framework, which she terms "friction-weighted choice," posits that the metabolic cost of sustained decision-making operates as an implicit surcharge, one that traditional models fail to capture because they treat the act of choosing as costless.', $lyceon_json$[{"key":"A","text":"A researcher's findings challenge a standard economic assumption by showing that the effort required to complete a purchase can function as a hidden cost that deters buyers independently of price."},{"key":"B","text":"Traditional economic models should be abandoned because they cannot account for the irrational tendencies that govern most consumer purchasing decisions."},{"key":"C","text":"Online retailers lose revenue primarily because their checkout interfaces require too many steps, a problem that could be solved through simpler website design."},{"key":"D","text":"Rajagopalan's study demonstrates that consumers consistently make purchasing decisions that contradict their own stated preferences about product quality."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Rajagopalan''s finding that checkout friction deters purchases even when price is unchanged, and her theoretical claim that the effort of choosing acts as an implicit cost that standard models ignore. The option stating that traditional models should be abandoned overstates the passage, which says they fail to capture one factor — it does not advocate their wholesale rejection. The suggestion that the passage is primarily about retailer revenue loss and website redesign latches onto one practical implication while missing the theoretical argument at the passage''s core. The claim that consumers contradict their stated preferences about product quality misreads the study: participants still rated the products as desirable but failed to complete the transaction due to cognitive depletion, not a change in quality assessment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LNNSQ6', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1847, the Hungarian physician Ignaz Semmelweis observed that the mortality rate from puerperal fever in a Vienna maternity ward staffed by medical students was 13.1%, compared with just 1.3% in an adjacent ward staffed by midwives. Semmelweis hypothesized that the medical students carried infectious material from autopsies to the delivery room on their hands. When he mandated handwashing with chlorinated lime solution, the mortality rate in the students'' ward fell to 1.7% within three months. Despite this dramatic result, Semmelweis''s colleagues largely rejected his theory; the germ model of disease would not gain wide acceptance for another two decades.', $lyceon_json$[{"key":"A","text":"Semmelweis demonstrated that a simple hygiene intervention could drastically reduce maternal deaths, yet his findings were not embraced by the medical community of his time."},{"key":"B","text":"The germ theory of disease was first proposed in 1847 by Ignaz Semmelweis in response to high mortality rates in Viennese hospitals."},{"key":"C","text":"Midwives in 19th-century Vienna were more effective caregivers than medical students because they followed stricter sanitation protocols."},{"key":"D","text":"Chlorinated lime solution was adopted as a standard antiseptic throughout European hospitals during the 1850s."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two linked points: Semmelweis''s handwashing intervention sharply reduced mortality, and his colleagues nevertheless rejected his theory. The option capturing both elements is the correct main idea. The claim that Semmelweis first proposed germ theory misreads the passage, which says the germ model gained acceptance later — it does not credit Semmelweis with originating it. The suggestion that midwives followed stricter sanitation protocols goes beyond the text, which only notes differing mortality rates without explaining midwife practices. The assertion that chlorinated lime became standard in the 1850s contradicts the passage''s statement that Semmelweis''s theory was largely rejected.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R3OYIX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if included in the text, would most effectively illustrate the claim made about Okonkwo?', E'In Chinua Achebe''s novel Things Fall Apart, the protagonist Okonkwo is driven by a consuming fear of resembling his father, Unoka, whom the community regarded as lazy and without title. Literary scholars have noted that this fear does not simply motivate Okonkwo''s ambition; it distorts his emotional life, causing him to suppress any feeling he associates with weakness — tenderness, uncertainty, grief — and to respond to vulnerability with aggression.', $lyceon_json$[{"key":"A","text":"\"Okonkwo's trajectory illustrates how colonial disruption destabilizes traditional Igbo governance structures.\""},{"key":"B","text":"\"Achebe's prose style in Things Fall Apart deliberately echoes the oral storytelling traditions of southeastern Nigeria.\""},{"key":"C","text":"\"Okonkwo's violence is not the expression of strength but the symptom of an interior panic; every harsh act is a flight from the softness he dreads.\""},{"key":"D","text":"\"The novel's depiction of Umuofia's harvest festivals reveals the economic foundations of communal prestige in pre-colonial Igbo society.\""}]$lyceon_json$::jsonb, 'C', NULL, E'The passage claims that Okonkwo''s fear of resembling his father distorts his emotional life, leading him to suppress vulnerability and respond with aggression. The quotation describing his violence as a symptom of interior panic and a flight from softness directly illustrates this psychological dynamic. The quotation about colonial disruption addresses a different theme in the novel — political destabilization — rather than Okonkwo''s personal emotional distortion. The quotation about Achebe''s prose style concerns narrative technique, not character psychology. The quotation about harvest festivals and economic prestige is thematically related to the novel but does not address the specific claim about Okonkwo''s fear-driven emotional suppression.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R5S0VT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The literary estate of novelist Miriam Okonkwo has authorized two scholars — Dr. Rene Villanueva and ______ to compile a comprehensive annotated bibliography of Okonkwo''s unpublished manuscripts, private correspondence, and marginalia found in the 347 volumes of her personal library.', $lyceon_json$[{"key":"A","text":"I —"},{"key":"B","text":"me —"},{"key":"C","text":"myself —"},{"key":"D","text":"mine —"}]$lyceon_json$::jsonb, 'B', NULL, E'The pronoun fills the second position in the compound object of the verb "has authorized": the estate authorized Dr. Rene Villanueva and [pronoun]. Because the pronoun functions as a direct object, the objective case "me" is required. The subjective case "I" is incorrect in the object position; removing the compound structure reveals that "the estate has authorized I" is ungrammatical. The reflexive "myself" requires an antecedent in the same clause referring to the same person, but no such antecedent exists here; "myself" cannot substitute for the objective pronoun in this construction. The possessive "mine" indicates ownership and cannot serve as the object of "authorized."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RH2DZY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to contrast gamelan tuning with Western musical conventions while citing an expert perspective. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a presentation on musicology, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TS5OI0', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Capuchin monkeys in the Serra da Capivara National Park have been observed cracking open cashew nuts using rounded quartzite stones. Researchers initially assumed this behavior was a recent development. However, excavations at tool-use sites revealed stone fragments with cashew residue dating back at least 3,000 years. [underlined: This finding makes capuchins one of the few non-human primates with an archaeologically documented tool tradition spanning millennia.]', $lyceon_json$[{"key":"A","text":"It states the broader significance of the research finding described earlier in the passage."},{"key":"B","text":"It provides a specific example that illustrates a claim made at the beginning of the passage."},{"key":"C","text":"It raises a question about the reliability of the archaeological method used by the researchers."},{"key":"D","text":"It introduces a contrasting interpretation of the excavation data presented in the passage."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence explains why the 3,000-year dating matters — it places capuchins among the rare non-human primates with a millennia-long documented tool tradition, which is the broader significance of the finding. The option about providing a specific example is wrong because the underlined sentence does not give a new example; it draws a conclusion from the evidence already presented. The option about questioning reliability is wrong because nothing in the sentence casts doubt on the methodology. The option about a contrasting interpretation is wrong because the sentence reinforces, rather than opposes, the excavation findings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U3GTAJ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Entomologist Priya Venkatesh has spent fourteen years cataloguing beetle species in the montane forests of the Western Ghats. Her team has identified over 370 species previously unknown to science. _______ Venkatesh cautions that the accelerating pace of deforestation in the region means many species may vanish before they are ever documented.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first two sentences describe the success of Venkatesh''s cataloguing work, while the sentence after the blank introduces a concern that undermines the optimism of that success: species may disappear before being documented. This is a concessive contrast — despite the achievements, a worrying reality persists. The concessive-contrast transition captures this shift. The addition transition is wrong because the final sentence does not simply add a parallel point; it introduces a counterpoint. The specification transition is wrong because the final sentence does not narrow or elaborate on the discovery count. The consequence transition is wrong because the caution about deforestation is not a logical result of the team''s discovery success — it is a contrasting concern.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UYBIX5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have found that Arctic bumblebees (Bombus polaris) can maintain a body temperature of 38°C even when ambient air drops to −5°C. The bees accomplish this by vibrating their flight muscles in rapid micro-contractions that generate metabolic heat without producing wing movement. This thermogenic strategy allows B. polaris to forage on willow catkins during brief Arctic summers when few other pollinators are active, giving the species near-exclusive access to early-blooming floral resources.', $lyceon_json$[{"key":"A","text":"Arctic bumblebees use a muscle-based heating mechanism that enables them to forage in extremely cold conditions."},{"key":"B","text":"Willow catkins depend entirely on Arctic bumblebees for pollination during the short summer season."},{"key":"C","text":"Scientists have recently discovered a new species of bumblebee that lives only in Arctic environments."},{"key":"D","text":"The flight muscles of Arctic bumblebees are structurally different from those of temperate bumblebee species."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Arctic bumblebees vibrate their flight muscles to generate heat, allowing them to forage in cold conditions — this is the central idea. The claim that willow catkins depend entirely on these bees overstates the passage, which says the bees have near-exclusive access but does not say the plants have no other pollinators. The suggestion that a new species was recently discovered misreads the passage, which discusses an existing species. The claim about structural differences in flight muscles is unsupported; the passage describes a behavioral strategy, not an anatomical distinction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W8127W', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the Voyager 1 spacecraft crossed into interstellar space in August 2012, it carried a golden record containing sounds and images intended to represent life on Earth. Among the 115 photographs encoded on the ______ which was assembled by a committee that astronomer Carl Sagan chaired in 1977, are depictions of human-constructed shelters, mathematical equations, and geological formations from six continents.', $lyceon_json$[{"key":"A","text":"record, which"},{"key":"B","text":"record; which"},{"key":"C","text":"record. Which"},{"key":"D","text":"record which"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause "which was assembled by a committee that astronomer Carl Sagan chaired in 1977" is a nonrestrictive relative clause providing additional information about the golden record. Because the record has already been uniquely identified ("the" golden record on Voyager 1), the clause is nonessential and must be set off by commas. A comma before "which" correctly introduces this nonrestrictive clause. The semicolon option incorrectly treats "which was assembled..." as an independent clause, creating a fragment after the semicolon. The period option similarly produces a sentence fragment beginning with "Which." Omitting the comma before "which" fails to signal the nonrestrictive nature of the clause, violating the Standard English convention that nonrestrictive "which" clauses require preceding commas.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W8T0DV', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In the spring of 2019, marine archaeologist Leila Farzan returned to a shipwreck site off the coast of Oman after a three-year hiatus. Diving to a depth of thirty-seven meters, ______ a sealed bronze amphora containing seventy-three silver coins dating to the ninth century, a discovery that fundamentally altered scholarly understanding of medieval Indian Ocean trade routes.', $lyceon_json$[{"key":"A","text":"she was discovering"},{"key":"B","text":"she has discovered"},{"key":"C","text":"she discovers"},{"key":"D","text":"she discovered"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage establishes a past-tense narrative: Farzan "returned" to the site in 2019. The verb in the blank must maintain this past-tense framework. The simple past "discovered" correctly describes a completed action within the established past narrative. The past progressive "was discovering" incorrectly implies an ongoing, incomplete action, which conflicts with the specific nature of finding a single artifact. The present perfect "has discovered" shifts to a tense connecting past action to the present, breaking the passage''s consistent past-time frame. The present tense "discovers" shifts entirely out of the past narrative, creating an incongruous tense change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WDEHM9', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Conservationists reintroduced red kites to central England in the early 1990s, releasing 93 birds over five years. By 2022, the population had grown to an estimated 6,000 breeding pairs, making the program one of the most successful raptor reintroductions in European history. Ornithologists attribute the rapid growth partly to the birds'' generalist diet — red kites readily scavenge roadkill, visit garden feeding stations, and hunt small rodents — and partly to the legal protections that shield them from persecution. Given these factors, the red kite reintroduction suggests that ________', $lyceon_json$[{"key":"A","text":"raptor species with flexible feeding habits and strong legal safeguards can recover quickly once reestablished in suitable habitat."},{"key":"B","text":"all European raptor species would benefit from similar reintroduction programs if sufficient funding were provided."},{"key":"C","text":"legal protections alone are sufficient to ensure the long-term survival of any endangered bird species."},{"key":"D","text":"red kites are now so numerous in central England that they pose a threat to native songbird populations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage identifies two factors behind the red kite''s success — dietary flexibility and legal protections — and describes a rapid population rebound. The inference that species with flexible diets and legal safeguards can recover quickly follows logically from these stated factors. The claim that all European raptors would benefit from similar programs extends far beyond what the passage supports, since it discusses only one species with particular traits. The suggestion that legal protections alone are sufficient ignores the passage''s emphasis on dietary flexibility as a contributing factor. The assertion that red kites threaten songbird populations introduces an ecological consequence the passage never mentions or implies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X39TBK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dr. Amara Osei, a materials scientist at the University of Ghana, has developed a lightweight building composite derived from coconut husk fibers. Traditional construction materials such as concrete require significant energy to ______ Osei''s composite can be manufactured at ambient temperatures, reducing both production costs and carbon emissions by nearly forty percent.', $lyceon_json$[{"key":"A","text":"produce, Osei's"},{"key":"B","text":"produce Osei's"},{"key":"C","text":"produce: Osei's"},{"key":"D","text":"produce; Osei's"}]$lyceon_json$::jsonb, 'D', NULL, E'The text presents two independent clauses: "Traditional construction materials such as concrete require significant energy to produce" and "Osei''s composite can be manufactured at ambient temperatures." A semicolon correctly joins two independent clauses that are closely related in meaning. The comma-only option creates a comma splice, which improperly joins two independent clauses without a coordinating conjunction. Omitting all punctuation produces a run-on sentence. The colon option is incorrect because the second clause does not explain, define, or elaborate on the first clause; instead, it introduces a contrasting piece of information about a different material.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y13R0E', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Geothermal energy production in Iceland has long been celebrated as a model of renewable resource use. The island''s volcanic geology provides virtually limitless heat, and the technology to convert that heat into electricity is well established. Yet recent studies from the Reykjanes Peninsula have shown that aggressive drilling can trigger micro-seismic events measuring up to 4.0 on the Richter scale, damaging nearby infrastructure. Some geologists now argue that current extraction rates are outpacing the natural recharge of subsurface reservoirs, potentially shortening the productive lifespan of individual wells by decades.', $lyceon_json$[{"key":"A","text":"It presents a widely held positive view and then introduces evidence that complicates that view."},{"key":"B","text":"It describes two competing scientific hypotheses and evaluates each on the basis of experimental data."},{"key":"C","text":"It traces the historical development of a technology and then predicts its future applications."},{"key":"D","text":"It summarizes a researcher's findings and then explains the methodology behind those findings."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first describes Iceland''s celebrated geothermal model (the positive view) and then introduces complications — micro-seismic events and reservoir depletion — that challenge that optimistic picture. The option about two competing hypotheses is wrong because the passage does not present two equal hypotheses; it starts from a consensus view and complicates it. The option about tracing historical development and predicting future applications is wrong because the passage does not provide a chronological history or discuss new applications. The option about summarizing findings and explaining methodology is wrong because the passage does not describe any specific research methodology.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YA3OA3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ornithologist Dmitri Volkov has documented the migration patterns of the bar-tailed godwit, a shorebird capable of extraordinary endurance flights. Covering roughly 11,500 kilometers from Alaska to New Zealand without ______ the bar-tailed godwit holds the record for the longest known nonstop flight of any land bird.', $lyceon_json$[{"key":"A","text":"rest; the"},{"key":"B","text":"rest. The"},{"key":"C","text":"rest, the"},{"key":"D","text":"rest the"}]$lyceon_json$::jsonb, 'C', NULL, E'The phrase "Covering roughly 11,500 kilometers from Alaska to New Zealand without rest" is an introductory participial phrase modifying "the bar-tailed godwit." A comma is required after an introductory participial phrase to separate it from the main clause. The semicolon option incorrectly treats the participial phrase as an independent clause, creating a fragment before the semicolon. The period option similarly creates a sentence fragment. Omitting all punctuation produces a run-on that merges the introductory phrase into the main clause without any separation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z39ELU', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neurobiologist Ekua Mensah''s experiments, conducted between 2017 and 2023 at a marine research station on the coast of Ghana, demonstrated that octopuses can solve multi-step puzzles by observing conspecifics. Her most striking finding — that naive octopuses matched the performance of trained individuals after watching just three ______ has prompted researchers in comparative cognition to reconsider whether invertebrate neural architectures can support observational learning.', $lyceon_json$[{"key":"A","text":"demonstrations — has"},{"key":"B","text":"demonstrations, has"},{"key":"C","text":"demonstrations; has"},{"key":"D","text":"demonstrations has"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence uses a pair of em dashes to set off the parenthetical clause "that naive octopuses matched the performance of trained individuals after watching just three demonstrations." Because the parenthetical was opened with an em dash after "finding," it must be closed with a matching em dash before the main verb "has prompted." The comma option fails to match the opening em dash, creating an asymmetric and non-standard punctuation pattern. The semicolon option incorrectly splits the sentence at a point where no independent clause boundary exists, fragmenting the subject ("Her most striking finding") from its verb ("has prompted"). Omitting all punctuation leaves the dash-enclosed parenthetical unclosed, making the sentence structure ambiguous and the main verb "has" difficult to parse as belonging to the subject "Her most striking finding."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
